<?php

declare(strict_types=1);

namespace App\Models;

use App\Support\Ids\HasPrefixedId;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;
use Illuminate\Support\Carbon;

/* @properties-start (generated by dev:model-docs) */
/**
 * @property string $id
 * @property string $title
 * @property string $body
 * @property array $channels
 * @property array $audience
 * @property string|null $link
 * @property string $status
 * @property int $recipients_count
 * @property Carbon|null $scheduled_at
 * @property Carbon|null $sent_at
 * @property string $created_by
 * @property Carbon|null $created_at
 * @property Carbon|null $updated_at
 */
/* @properties-end */
class Broadcast extends Model
{
    use HasPrefixedId;

    protected static string $idPrefix = 'brc';

    protected $fillable = [
        'title', 'body', 'channels', 'audience', 'link', 'status', 'recipients_count', 'scheduled_at', 'sent_at',
        'created_by',
    ];

    protected function casts(): array
    {
        return [
            'channels' => 'array',
            'audience' => 'array',
            'scheduled_at' => 'datetime',
            'sent_at' => 'datetime',
        ];
    }

    /** @return BelongsTo<User, $this> */
    public function author(): BelongsTo
    {
        return $this->belongsTo(User::class, 'created_by');
    }
}
